async function cliBrowserSetup(pane=null){
 if($('#modal').open)return;
 const remote=pane?.type==='ssh',info=await api.browserCLIInfo();
 const d=modal(`<section id="cli-setup"><div class="shortcuts-heading"><h2>CLI Browser Access</h2><button id="close-cli-setup" class="icon-button" aria-label="Close CLI setup">${icon('close')}</button></div><p>${remote?`Enable access for this SSH session (${escape(pane.label)}). The helper is installed in your remote home folder and connects through this SSH session.`:'Any CLI or coding agent can open the right-hand browser with this command.'}</p><pre class="cli-command">zawo browser open
zawo browser open http://localhost:3000</pre>${remote?'<button id="enable-cli-browser" class="button primary">Enable for this SSH session</button>':`<p>${info.error?escape(info.error):'The local command is installed at '+escape(info.command)+'. If it is not on your PATH, run this before starting your CLI:'}</p><pre class="cli-command">${escape(info.activation)}</pre>`}<div id="cli-activation" hidden><h3>Run before starting your coding agent</h3><textarea readonly rows="3" aria-label="CLI activation command"></textarea><p>Click the command, copy it, and run it in this remote terminal. Then start your coding agent. Access ends when this SSH session disconnects.</p></div><p class="form-error" id="cli-error"></p><h3>Tell your coding agent</h3><p class="cli-agent-note">After starting the development server, run <code>zawo browser open &lt;preview-url&gt;</code> to open it in Zawo. Use the full HTTP or HTTPS URL.</p><p>${remote?'Remote localhost pages are forwarded automatically. Public websites open directly on this Mac. Other remote private addresses require a saved forwarding rule.':'Configure your AI tool to use Zawo when you say “open the browser”.'}</p>${remote?'':'<button id="open-agent-integrations" class="button">AI tool integrations…</button>'}</section>`);
 d.classList.add('shortcuts-dialog');d.addEventListener('close',()=>d.classList.remove('shortcuts-dialog'),{once:true});$('#open-agent-integrations')?.addEventListener('click',()=>{d.close();agentIntegrationsSetup();});$('#close-cli-setup').onclick=()=>d.close();
 $('#enable-cli-browser')?.addEventListener('click',async()=>{const button=$('#enable-cli-browser');button.disabled=true;button.textContent='Enabling…';try{const result=await api.enableBrowserCLI(pane.id);if(!d.open)return;$('#cli-activation').hidden=false;const field=$('#cli-activation textarea');field.value=result.activation;field.onclick=()=>field.select();button.textContent='Enabled for this session';}catch(e){if(d.open){$('#cli-error').textContent=message(e);button.disabled=false;button.textContent='Retry';}}});
}
async function agentIntegrationsSetup(){
 if($('#modal').open)return;
 let info;try{info=await api.agentIntegrations();}catch(e){toast(message(e),true);return;}
 const d=modal(`<section id="agent-integrations"><div class="shortcuts-heading"><h2>AI Tool Integrations</h2><button id="close-agent-integrations" class="icon-button" aria-label="Close AI integrations">${icon('close')}</button></div><p>Say “open the browser” or “打开浏览器” to open a new tab in Zawo. A request with a URL opens that page.</p><div id="agent-integration-list"></div><p class="form-error" id="agent-integration-error" role="status"></p><p class="integration-note">These rules apply to new AI sessions on this Mac. Your existing instructions are preserved and backed up. Remove deletes only the Zawo section. Tool permissions and project rules still apply.</p><details><summary>Other tools and SSH sessions</summary><p>Any tool that can run shell commands can use <code>zawo browser open [URL]</code>. Copy the rule into its instruction settings. In SSH sessions, enable CLI browser access and run the provided PATH command first; configure the agent’s rules on that remote computer.</p><button id="copy-agent-rules" class="button">Copy browser rule</button><pre id="agent-rules-preview" class="cli-command"></pre></details></section>`);
 d.classList.add('shortcuts-dialog');d.addEventListener('close',()=>d.classList.remove('shortcuts-dialog'),{once:true});$('#close-agent-integrations').onclick=()=>d.close();$('#agent-rules-preview').textContent=info.rules;
 const render=()=>{$('#agent-integration-list').innerHTML=info.agents.map(a=>`<div class="integration-row"><div><strong>${escape(a.name)}</strong><span>${a.error?escape(a.error):a.installed?(a.current?'Configured':'Update available'):'Not configured'}</span><small>${escape(a.path)}</small></div><div class="integration-actions">${!a.current?`<button class="button" data-agent-install="${escape(a.id)}" ${a.error?'disabled':''}>${a.installed?'Update':'Configure'}</button>`:''}${a.installed?`<button class="text-button" data-agent-remove="${escape(a.id)}">Remove</button>`:''}</div></div>`).join('');
  const update=async(id,enabled)=>{$$('#agent-integration-list button').forEach(b=>b.disabled=true);$('#agent-integration-error').textContent='';try{info=await api.setAgentIntegration(id,enabled);if(d.open){render();toast(enabled?'Configured. Start a new AI session to use Zawo.':'Zawo rule removed.');}}catch(e){if(d.open){render();$('#agent-integration-error').textContent=message(e);}}};
  $$('[data-agent-install]').forEach(b=>b.onclick=()=>update(b.dataset.agentInstall,true));$$('[data-agent-remove]').forEach(b=>b.onclick=()=>update(b.dataset.agentRemove,false));
 };render();$('#copy-agent-rules').onclick=()=>safe(async()=>{await api.copyAgentRules();toast('Browser rule copied');});
}
function shortcutHelp(){
 if($('#modal').open)return;
 const groups=['Tabs','Workspace','Terminal','Browser'];
 const rows=shortcuts.filter(s=>s.id!=='help'&&!/^tab-[2-9]$/.test(s.id)&&!['focus-right','focus-up','focus-down'].includes(s.id));
 const previous=document.activeElement;
 const d=modal(`<section id="shortcuts-help"><div class="shortcuts-heading"><h2>Keyboard Shortcuts</h2><button id="close-shortcuts" class="icon-button" aria-label="Close keyboard shortcuts">${icon('close')}</button></div><p>⌘ Command &nbsp; ⇧ Shift &nbsp; ⌥ Option<br>Control keys remain available to your terminal.</p>${groups.map(group=>`<section class="shortcut-group"><h3>${group}</h3>${rows.filter(s=>s.group===group).map(s=>`<div class="shortcut-row"><span>${s.id==='tab-1'?'Select terminal tab 1–9':s.id==='focus-left'?'Move between split terminals':escape(s.label)}</span><kbd>${s.id==='tab-1'?'⌘1–9':s.id==='focus-left'?'⌘⌥ ← ↑ ↓ →':escape(s.hint)}</kbd></div>`).join('')}</section>`).join('')}<p class="shortcut-note">Tab shortcuts select the tabs across the top. Workspace arrows move between split terminals.<br>When the browser is focused, ⌘T / ⌘W manage browser tabs and ⌘L selects its address bar. Terminal navigation pauses while a dialog or editor is open.</p></section>`);
 d.classList.add('shortcuts-dialog');
 $('#close-shortcuts').onclick=()=>d.close();d.addEventListener('close',()=>{d.classList.remove('shortcuts-dialog');if(previous?.isConnected)previous.focus();},{once:true});$('#close-shortcuts').focus();
}
function runShortcut(id){
 if(id==='help'){shortcutHelp();return;}
 if($('#modal').open)return;
 if(!$('#drawer-layer').hidden){if(id==='close-tab')closeDrawer();return;}
 const browserFocused=document.activeElement?.closest('#browser-panel,.browser-heading');
 if(browserFocused&&['new-tab','close-tab','local'].includes(id)){
  if(id==='local'){$('#browser-address').focus();$('#browser-address').select();}
  else safe(()=>api.browserAction(id==='new-tab'?'new-tab':'close-tab'));return;
 }
 const tab=tabs.find(t=>t.id===activeTab);
 const select=t=>{if(t){activeTab=t.id;setView('terminal');}};
 if(/^tab-[1-9]$/.test(id)){select(tabs[Number(id.slice(4))-1]);return;}
 if(id==='next-tab'||id==='previous-tab'){if(tabs.length)select(tabs[(Math.max(0,tabs.indexOf(tab))+(id==='next-tab'?1:tabs.length-1))%tabs.length]);return;}
 if(id.startsWith('focus-')){if(view!=='terminal'||!tab)return;const target=terminalMap.get(adjacentPane(tab.layout,tab.focusedPaneId,id.slice(6)));if(target){focusPane(target);if(tab.focusMode)renderTerminalStage();else target.terminal.focus();}return;}
 if(id==='workspace-view'){if(view==='terminal'&&tab?.panes.length>1)setWorkspaceFocus(tab,tab.focusMode?null:terminalMap.get(tab.focusedPaneId));return;}
 if(id==='new-tab'||id==='quick-connect')setView('new-tab');
 else if(id==='local')safe(()=>openLocal());
 else if(id==='close-tab'){if(view==='new-tab')setView(activeTab?'terminal':'hosts');else if(view==='terminal'&&tab)safe(()=>closeTab(tab.id));}
 else if(id==='find'&&view==='terminal')terminalActions.search();
 else if(id==='browser')$('#toggle-browser').click();
}
document.addEventListener('keydown',e=>{const id=matchShortcut(e);if(!id)return;e.preventDefault();e.stopImmediatePropagation();runShortcut(id);},true);
